class Main {
    public static void main(String[] args) {
        // 자릿수를 셀 양의 정수예요.
        int n = 4096;
        // 나눈 횟수를 세요.
        int count = 0;
        // 조건이 참인 동안 반복해요.
        while (n > 10) {
            // 끝자리를 하나 지우고 횟수를 더해요.
            n /= 10;
            count++;
        }
        System.out.println("자릿수: " + count);
    }
}
